// Generated by `just generate` from `src/plugins/dotclaude-lab/slices/schema/adapters/cli.ts`. Edit the source and run `just generate`.
// Writes the JSON Schema of Claude Code `settings.json` and `managed-settings.json` from the installed bundle.
// The `dotclaude-schema` bin calls `main`.
//
//   dotclaude-schema --out DIR [--bundle FILE] [--version X.Y.Z]
//
// `--out` is required, so the command never writes into a folder by chance.
// A repository that keeps the files in `schemas/` passes `--out schemas`.
// `--bundle` defaults to the file that `claude` on `PATH` resolves to.
// `--version` defaults to the version in the name of the bundle, or the output of `--version`.
// The command reads the bundle and never changes it.
// The domain code in `../domain/build.ts` builds the schemas, and this file does the I/O.

import fs from "node:fs";
import path from "node:path";
import { buildSchemas, type SchemaKind, schemaFiles } from "../domain/build.ts";

const USAGE =
  "Usage: dotclaude-schema --out DIR [--bundle FILE] [--version X.Y.Z]";

/** The value after `name` in `argv`, or undefined. */
const opt = (argv: string[], name: string): string | undefined => {
  const at = argv.indexOf(name);
  return at < 0 ? undefined : argv[at + 1];
};

/** The bundle that `claude` on `PATH` resolves to. */
const installedBundle = (): string => {
  const bin = Bun.which("claude");
  if (!bin) throw new Error("claude is not on PATH.");
  return fs.realpathSync(bin);
};

/** The version in the name of the bundle, or in the output of `bundle --version`. */
export const versionOf = (bundle: string): string => {
  const base = path.basename(bundle);
  if (/^\d+\.\d+\.\d+$/.test(base)) return base;
  const r = Bun.spawnSync([bundle, "--version"]);
  if (r.exitCode !== 0)
    throw new Error(`${bundle} --version exited with ${r.exitCode}.`);
  return /\d+\.\d+\.\d+/.exec(r.stdout.toString())?.[0] ?? "unknown";
};

/** Builds both schemas, then writes them to `outDir`. Writes nothing when the build throws. */
const writeSchemas = async (
  src: string,
  version: string,
  outDir: string,
): Promise<{ names: Record<SchemaKind, string>; count: number }> => {
  const schemas = buildSchemas(src, version);
  const names = schemaFiles();
  fs.mkdirSync(outDir, { recursive: true });
  for (const kind of ["user", "managed"] as const)
    await Bun.write(
      path.join(outDir, names[kind]),
      `${JSON.stringify(schemas[kind], null, 2)}\n`,
    );
  return {
    names,
    count: Object.keys(schemas.user.properties ?? {}).length,
  };
};

/** Runs the command with `argv`, and returns the exit code. */
export const main = async (argv: string[]): Promise<number> => {
  if (argv.includes("--help") || argv.includes("-h")) {
    console.log(USAGE);
    return 0;
  }
  const outDir = opt(argv, "--out");
  if (!outDir) {
    console.error(`schema: --out is required.\n${USAGE}`);
    return 2;
  }
  try {
    const bundle = opt(argv, "--bundle") ?? installedBundle();
    const version = opt(argv, "--version") ?? versionOf(bundle);
    // The bundle holds bytes that are not UTF-8, so it is read as latin1.
    const src = Buffer.from(await Bun.file(bundle).arrayBuffer()).toString(
      "latin1",
    );
    const { names, count } = await writeSchemas(
      src,
      version,
      path.resolve(outDir),
    );
    console.log(`Claude Code ${version}: ${count} top-level keys`);
    for (const name of Object.values(names))
      console.log(path.join(path.resolve(outDir), name));
    return 0;
  } catch (err) {
    console.error(`schema: ${(err as Error).message}`);
    return 1;
  }
};
